<!doctype html><html lang="ro"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:10px}h1{font-size:18px;margin:0 0 4px}p{color:#526070;margin:0 0 18px}table{border-collapse:collapse;width:100%}th{background:#e8eef8;text-align:left}th,td{border:1px solid #cbd5e1;padding:7px}td.money{text-align:right}.total{margin-top:14px;text-align:right;font-size:12px;font-weight:bold}</style></head><body><h1>Raport recepții furnizori</h1><p>Generat la {{ now()->format('d.m.Y H:i') }} · {{ $receptions->count() }} recepții</p><table><thead><tr><th>NIR</th><th>Data</th><th>Furnizor</th><th>Gestiune</th><th>Total</th></tr></thead><tbody>@foreach($receptions as $reception)<tr><td>{{ $reception->number }}</td><td>{{ optional($reception->received_at)->format('d.m.Y') }}</td><td>{{ $reception->supplier?->name ?? '—' }}</td><td>{{ $reception->warehouse?->name ?? '—' }}</td><td class="money">{{ number_format((float) $reception->total, 2, ',', '.') }} {{ $reception->currency ?: 'RON' }}</td></tr>@endforeach</tbody></table><div class="total">Total recepționat: {{ number_format((float) $receptions->sum('total'), 2, ',', '.') }} RON</div></body></html>
